(()=>{'use strict';if(!document.body.classList.contains('shared-app'))return;let mode='calendar',generation=0;const previous=renderProgram;renderProgram=async function(){const token=++generation;await previous();if(token!==generation||scope!=='program'||!project||window.SAMANDIS_PERSONAL_MODE)return;const root=el('#sharedContent');if(mode==='gantt'){try{const milestones=await checked(db.from('sm_milestones').select('*').eq('project_id',project.id).order('due'));if(token!==generation||scope!=='program')return;const rows=[...tasks.filter(t=>t.due).map(t=>({id:t.id,title:t.title,start:(t.starts_on||t.created_at||t.due).slice(0,10),due:t.due,status:labels[t.status],done:t.status==='done'})),...milestones.map(m=>({id:m.id,title:m.title,start:m.starts_on,due:m.due,status:'موعد تحویل',delivery:true}))];const dates=rows.flatMap(r=>[r.start,r.due]).filter(Boolean).sort(),parse=s=>new Date(s+'T12:00:00Z').getTime(),lo=parse(dates[0]||new Date().toISOString().slice(0,10))-86400000,hi=parse(dates.at(-1)||new Date().toISOString().slice(0,10))+86400000,span=Math.max(86400000,hi-lo),pos=s=>(parse(s)-lo)/span*100,fmt=s=>date(s);root.innerHTML='<section class="panel"><div class="panel-header"><h2>گانت پروژه</h2><small>بازهٔ کارها: تاریخ تعریف تا مهلت · زرد: موعد تحویل</small></div><div class="timeline-shell"><div class="timeline"><div class="time-header"><div class="time-label">کار و بازهٔ زمانی</div><div class="time-scale">'+Array.from({length:6},(_,i)=>'<span>'+fmt(new Date(lo+span*i/5).toISOString().slice(0,10))+'</span>').join('')+'</div></div>'+rows.map(r=>'<div class="time-row"><div class="time-label"><button class="task-title" data-gantt-id="'+esc(r.id)+'" '+(r.delivery?'disabled':'')+'>'+esc(r.title)+'</button><small>'+fmt(r.start)+' تا '+fmt(r.due)+'</small></div><div class="time-track"><button class="time-bar '+(r.delivery?'delivery':'')+' '+(r.done?'completed':'')+'" style="right:'+Math.max(0,pos(r.start))+'%;width:'+Math.max(1,pos(r.due)-pos(r.start))+'%" data-gantt-id="'+esc(r.id)+'" '+(r.delivery?'disabled':'')+' title="'+esc(r.title)+'">'+esc(r.status)+'</button></div></div>').join('')+(rows.length?'':'<div class="shared-empty">برای نمایش گانت، مهلت کارها را مشخص کنید.</div>')+'</div></div></section><p class="shared-meta">'+fa(tasks.filter(t=>!t.due).length)+' کار بدون مهلت در گانت نمایش داده نمی‌شود.</p>';root.querySelectorAll('[data-gantt-id]:not(:disabled)').forEach(b=>b.onclick=()=>detail(b.dataset.ganttId))}catch(e){message(failure(e))}}root.insertAdjacentHTML('afterbegin','<div class="program-switch" role="group" aria-label="نمای برنامه"><button data-program-mode="calendar" class="'+(mode==='calendar'?'active':'')+'">تقویم</button><button data-program-mode="gantt" class="'+(mode==='gantt'?'active':'')+'">گانت و تایملاین</button></div>');root.querySelectorAll('[data-program-mode]').forEach(b=>b.onclick=()=>{mode=b.dataset.programMode;renderProgram()})};})();
